css:
body, html {
    margin: 0;
    padding: 0;
    font-family: Tahoma, Arial, sans-serif;
    direction: rtl;
    background-color: #f7f7f7;
    width: 100%;
}
.container {
    width: 100%;
    padding: 40px;
    background-color: #ffffff;
    box-sizing: border-box;
}
.header {
    display: flex;
    align-items: center;
    margin-bottom: 40px;
}
.employee-photo {
    width: 120px;
    height: 120px;
    border-radius: 50%;
    border: 2px solid #00844E;
    object-fit: cover;
    margin-left: 20px;
}
.employee-info {
    flex: 1;
    text-align: right;
}
h1 {
    font-size: 36px;
    color: #00844E;
    margin: 0;
}
.section {
    margin-bottom: 20px;
}
.section-title {
    font-size: 28px;
    color: #007BFF;
    margin-bottom: 10px;
}
.field-group {
    display: flex;
    flex-wrap: wrap;
    gap: 20px;
}
.field {
    flex: 1 1 calc(50% - 20px);
    display: flex;
    justify-content: space-between;
    padding: 10px 0;
    border-bottom: 1px solid #e0e0e0;
}
.field-label {
    font-weight: bold;
    color: #333;
    width: 40%;
}
.field-value {
    color: #555;
    width: 60%;
    text-align: right;
}
.iban-status {
    color: red;
    font-weight: bold;
}
.verified {
    color: green;
}
.letter-head, .footer {
    text-align: center;
    margin-bottom: 20px;
    font-size: 18px;
}

html:
{% import "afmco/templates/print/identity.html" as afm %}{{ afm.styles() }}
{% if letter_head and not no_letterhead -%}
<div class="letter-head">{{ letter_head }}</div>
{% endif %}
{{ afm.strip() }}

<div class="container">
    <div class="header">
        <img src="{{ doc.image }}" alt="{{ _("Employee Photo", "ar", "Employee Profile") }}" class="employee-photo">
        <div class="employee-info">
            <h1>{{ _("Employee Profile", "ar", "Employee Profile") }}</h1>
            <p>{{ doc.employee_name }}</p>
            <p>{{ doc.designation }}</p>
            <p>{{ doc.department }}</p>
        </div>
    </div>

    {% if doc.employee_number or doc.date_of_joining or doc.nationality or doc.city or doc.date_of_birth %}
    <div class="section">
        <div class="section-title">{{ _("Basic Information", "ar", "Employee Profile") }}</div>
        <div class="field-group">
            {% if doc.employee_number %}
            <div class="field">
                <div class="field-label">{{ _("Employee Number", "ar", "Employee Profile") }}</div>
                <div class="field-value">{{ doc.employee_number }}</div>
            </div>
            {% endif %}
            {% if doc.date_of_joining %}
            <div class="field">
                <div class="field-label">{{ _("Date of Joining", "ar", "Employee Profile") }}</div>
                <div class="field-value">{{ doc.date_of_joining }}</div>
            </div>
            {% endif %}
            {% if doc.nationality %}
            <div class="field">
                <div class="field-label">{{ _("Nationality", "ar", "Employee Profile") }}</div>
                <div class="field-value">{{ doc.nationality }}</div>
            </div>
            {% endif %}
            {% if doc.city %}
            <div class="field">
                <div class="field-label">{{ _("City", "ar", "Employee Profile") }}</div>
                <div class="field-value">{{ doc.city }}</div>
            </div>
            {% endif %}
            {% if doc.date_of_birth %}
            <div class="field">
                <div class="field-label">{{ _("Date of Birth", "ar", "Employee Profile") }}</div>
                <div class="field-value">{{ doc.date_of_birth }}</div>
            </div>
            {% endif %}
        </div>
    </div>
    {% endif %}

    {% if doc.personal_email or doc.company_email or doc.cell_number %}
    <div class="section">
        <div class="section-title">{{ _("Contact", "ar", "Employee Profile") }}</div>
        <div class="field-group">
            {% if doc.personal_email %}
            <div class="field">
                <div class="field-label">{{ _("Personal Email", "ar", "Employee Profile") }}</div>
                <div class="field-value">{{ doc.personal_email }}</div>
            </div>
            {% endif %}
            {% if doc.company_email %}
            <div class="field">
                <div class="field-label">{{ _("Company Email", "ar", "Employee Profile") }}</div>
                <div class="field-value">{{ doc.company_email }}</div>
            </div>
            {% endif %}
            {% if doc.cell_number %}
            <div class="field">
                <div class="field-label">{{ _("Mobile Number", "ar", "Employee Profile") }}</div>
                <div class="field-value">{{ doc.cell_number }}</div>
            </div>
            {% endif %}
        </div>
    </div>
    {% endif %}

    {% if doc.bank_name or doc.bank_ac_no or doc.iban %}
    <div class="section">
        <div class="section-title">{{ _("Bank Details", "ar", "Employee Profile") }}</div>
        <div class="field-group">
            {% if doc.bank_name %}
            <div class="field">
                <div class="field-label">{{ _("Bank Name", "ar", "Employee Profile") }}</div>
                <div class="field-value">{{ doc.bank_name }}</div>
            </div>
            {% endif %}
            {% if doc.bank_ac_no %}
            <div class="field">
                <div class="field-label">{{ _("Bank Account Number", "ar", "Employee Profile") }}</div>
                <div class="field-value">{{ doc.bank_ac_no }}</div>
            </div>
            {% endif %}
            {% if doc.iban %}
            <div class="field">
                <div class="field-label">{{ _("IBAN", "ar", "Employee Profile") }}</div>
                <div class="field-value">{{ doc.iban }}</div>
            </div>
            <div class="field">
                <div class="field-label">{{ _("IBAN Verification Status", "ar", "Employee Profile") }}</div>
                <div class="field-value {{ 'verified' if doc.iban_verified == 1 else 'iban-status' }}">
                    {{ '✔️ ' ~ _("Verified", "ar", "Employee Profile") if doc.iban_verified == 1 else '✖️ ' ~ _("Not Verified", "ar", "Employee Profile") }}
                </div>
            </div>
            {% endif %}
        </div>
    </div>
    {% endif %}

    {% if doc.employment_type or doc.marital_status or doc.occupation or doc.iqama_expiration_date %}
    <div class="section">
        <div class="section-title">{{ _("Other Details", "ar", "Employee Profile") }}</div>
        <div class="field-group">
            {% if doc.employment_type %}
            <div class="field">
                <div class="field-label">{{ _("Employment Type", "ar", "Employee Profile") }}</div>
                <div class="field-value">{{ doc.employment_type }}</div>
            </div>
            {% endif %}
            {% if doc.marital_status %}
            <div class="field">
                <div class="field-label">{{ _("Marital Status", "ar", "Employee Profile") }}</div>
                <div class="field-value">{{ doc.marital_status }}</div>
            </div>
            {% endif %}
            {% if doc.occupation %}
            <div class="field">
                <div class="field-label">{{ _("Designation", "ar", "Employee Profile") }}</div>
                <div class="field-value">{{ doc.occupation }}</div>
            </div>
            {% endif %}
            {% if doc.iqama_expiration_date %}
            <div class="field">
                <div class="field-label">{{ _("Iqama Expiry Date", "ar", "Employee Profile") }}</div>
                <div class="field-value">{{ doc.iqama_expiration_date }}</div>
            </div>
            {% endif %}
        </div>
    </div>
    {% endif %}
</div>

{% if footer and not no_footer %}
<div class="footer">{{ footer }}</div>
{% endif %}
